          {

            *q++=(JSAMPLE) ScaleQuantumToChar(GetPixelRed(image,p));

            *q++=(JSAMPLE) ScaleQuantumToChar(GetPixelGreen(image,p));

            *q++=(JSAMPLE) ScaleQuantumToChar(GetPixelBlue(image,p));

            p+=GetPixelChannels(image);

          }

